<script setup lang="ts">
import { onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, problem, validation } from '../api'
import type { AgentConfig, ApiProblem, Comparison, Dataset, Experiment, ExperimentInput, Run, ScoreSet } from '../types'
import { allPages, date, jsonObject, metricNames, number, pretty, query, sourceNames, stateNames } from '../workbench'
import AsyncState from '../components/AsyncState.vue'
import ProblemBox from '../components/ProblemBox.vue'
import FormModal from '../components/FormModal.vue'
import RunPicker from '../components/RunPicker.vue'
import SummaryPanel from '../components/SummaryPanel.vue'
const route = useRoute(), router = useRouter()
const experiments = ref<Experiment[]>([]), total = ref(0), page = ref(1), loading = ref(true), error = ref<ApiProblem | null>(null)
const selected = ref<Experiment | null>(null), runs = ref<Run[]>([]), runTotal = ref(0), runPage = ref(1), historyLoading = ref(false), historyError = ref<ApiProblem | null>(null)
const modal = ref(false), editId = ref<number>(), saving = ref(false), formError = ref<ApiProblem | null>(null), choicesLoading = ref(false)
const datasets = ref<Dataset[]>([]), agents = ref<AgentConfig[]>([]), notice = ref(''), actionError = ref<ApiProblem | null>(null)
const form = reactive<ExperimentInput>({ name: '', dataset_id: 0, agent_config_id: 0, version_label: '', purpose: '' })
const startModal = ref(false), rescoreModal = ref(false), pendingRun = ref<Run | null>(null), currentRun = ref<Run | null>(null), currentScoreSet = ref<ScoreSet | null>(null), progressError = ref<ApiProblem | null>(null), progressLoading = ref(false)
const judgeJson = ref('{}'), ruleJson = ref('{}'), budgetJson = ref('{"total_timeout_seconds": 1800, "max_total_calls": 120}')
const requestId = ref(''), left = ref(query(route.query.left)), right = ref(query(route.query.right)), leftScore = ref(query(route.query.left_score)), rightScore = ref(query(route.query.right_score)), comparison = ref<Comparison | null>(null), comparing = ref(false), compareError = ref<ApiProblem | null>(null)
let trackingGeneration = 0; let disposed = false, timer: ReturnType<typeof setTimeout> | undefined
function remember(extra: Record<string, string | undefined>) { void router.replace({ query: { ...route.query, ...extra } }) }
async function load() { loading.value = true; error.value = null; try { const data = await api.experiments(page.value); experiments.value = data.items; total.value = data.total; const id = Number(route.query.experiment); if (id && !selected.value) { selected.value = await api.experiment(id); await loadHistory() } } catch (e) { error.value = problem(e) } finally { loading.value = false } }
async function loadHistory() { if (!selected.value) return; historyLoading.value = true; historyError.value = null; try { const data = await api.runs(runPage.value, selected.value.id); runs.value = data.items; runTotal.value = data.total } catch (e) { historyError.value = problem(e); runs.value = [] } finally { historyLoading.value = false } }
async function select(item: Experiment) { selected.value = item; runPage.value = 1; remember({ experiment: String(item.id) }); await loadHistory() }
async function edit(item?: Experiment) { editId.value = item?.id; Object.assign(form, item ? { name: item.name, dataset_id: item.dataset_id, agent_config_id: item.agent_config_id, version_label: item.version_label, purpose: item.purpose } : { name: '', dataset_id: 0, agent_config_id: 0, version_label: '', purpose: '' }); formError.value = null; modal.value = true; choicesLoading.value = true; try { [datasets.value, agents.value] = await Promise.all([allPages(p => api.datasets(p)), allPages(p => api.agents(p))]) } catch (e) { formError.value = problem(e) } finally { choicesLoading.value = false } }
async function save() { formError.value = validation([ ...(!form.name.trim() ? [{ field: 'name', message: '请输入实验名称' }] : []), ...(!form.dataset_id ? [{ field: 'dataset_id', message: '请选择数据集' }] : []), ...(!form.agent_config_id ? [{ field: 'agent_config_id', message: '请选择 Agent 配置' }] : []) ]); if (formError.value) return; saving.value = true; try { const item = await api.saveExperiment({ ...form, name: form.name.trim() }, editId.value); selected.value = item; remember({ experiment: String(item.id) }); modal.value = false; notice.value = '实验已保存。候选标签需要实际执行证据才能核验。'; await load(); await loadHistory() } catch (e) { formError.value = problem(e) } finally { saving.value = false } }
async function remove(item: Experiment) { if (!window.confirm(`删除实验“${item.name}”？历史运行仍可查询。`)) return; actionError.value = null; try { await api.deleteExperiment(item.id); if (selected.value?.id === item.id) { selected.value = null; runs.value = []; remember({ experiment: undefined }) } await load(); notice.value = '实验已删除，历史结果仍保留。' } catch (e) { actionError.value = problem(e) } }
function prepareStart() { startModal.value = true; formError.value = null; judgeJson.value = '{}'; ruleJson.value = '{}'; requestId.value = crypto.randomUUID() }
async function start() { if (!selected.value) return; formError.value = null; saving.value = true; try { const input = { request_id: requestId.value, judge_profile: jsonObject(judgeJson.value, 'Judge 配置'), rule_profile: jsonObject(ruleJson.value, '规则配置'), execution_budget: jsonObject(budgetJson.value, '执行预算') }; const result = await api.startExperiment(selected.value.id, input); startModal.value = false; notice.value = `运行已接受：${result.run_id}。处理完成与质量通过分别统计。`; remember({ run: result.run_id, score_set: undefined }); await loadHistory() } catch (e) { formError.value = problem(e) } finally { saving.value = false } }
function prepareRescore(run: Run) { pendingRun.value = run; judgeJson.value = pretty(run.snapshot.judge || {}); ruleJson.value = pretty(run.snapshot.rules || {}); formError.value = null; rescoreModal.value = true }
async function rescore() { if (!pendingRun.value) return; saving.value = true; formError.value = null; try { const result = await api.rescore({ source_run_id: pendingRun.value.id, judge_profile: jsonObject(judgeJson.value, 'Judge 配置'), rule_profile: jsonObject(ruleJson.value, '规则配置') }); rescoreModal.value = false; notice.value = `新评分集已接受：${result.id}，复用原回答。`; remember({ run: result.run_id, score_set: result.id }); currentScoreSet.value = result } catch (e) { formError.value = problem(e) } finally { saving.value = false } }
async function track(id: string, scoreSetId?: string) { const generation = ++trackingGeneration; if (timer) clearTimeout(timer); progressLoading.value = true; progressError.value = null; try { const [run, score] = await Promise.all([api.run(id), scoreSetId ? api.scoreSet(scoreSetId) : Promise.resolve(null)]); if (disposed || generation !== trackingGeneration) return; currentRun.value = run; currentScoreSet.value = score; const status = score?.status || run.status; if (['QUEUED', 'RUNNING'].includes(status)) timer = setTimeout(() => void track(id, scoreSetId), 2000); else await loadHistory() } catch (e) { if (generation === trackingGeneration) progressError.value = problem(e) } finally { if (generation === trackingGeneration) progressLoading.value = false } }
async function retryProgress() { const id = query(route.query.run), scoreId = query(route.query.score_set); if (id) await track(id, scoreId || undefined); else if (scoreId) { try { const score = await api.scoreSet(scoreId); await track(score.run_id, scoreId) } catch (e) { progressError.value = problem(e) } } else if (currentRun.value) await track(currentRun.value.id, currentScoreSet.value?.id) }
function pickLeft(id: string, score: string) { left.value = id; leftScore.value = score; comparison.value = null; remember({ left: id || undefined, left_score: score || undefined }) }
function pickRight(id: string, score: string) { right.value = id; rightScore.value = score; comparison.value = null; remember({ right: id || undefined, right_score: score || undefined }) }
async function compare() { compareError.value = null; comparison.value = null; if (!left.value || !right.value) { compareError.value = validation([{ field: 'run_id', message: '请选择左右两次运行' }]); return } comparing.value = true; try { comparison.value = await api.comparison(left.value, right.value, leftScore.value, rightScore.value) } catch (e) { compareError.value = problem(e) } finally { comparing.value = false } }
watch(() => [route.query.run, route.query.score_set], retryProgress, { immediate: true })
onMounted(async () => { await load(); if (left.value && right.value) await compare() })
onUnmounted(() => { disposed = true; if (timer) clearTimeout(timer) })
</script>
<template>
  <div class="page-heading"><div><div class="eyebrow">EXPERIMENTS / FROZEN CONDITIONS</div><h1>实验与版本对比</h1><p>每次执行独立保存；先核对条件，再查看共同有效样本的差异。</p></div><ElButton type="primary" @click="edit()">创建实验</ElButton></div>
  <div v-if="notice" class="notice" role="status">{{ notice }}</div><ProblemBox :error="actionError" />
  <section class="panel"><div class="panel-heading"><h2>实验记录 <span class="count-label">{{ total }}</span></h2><ElButton size="small" @click="load">刷新</ElButton></div><AsyncState :loading="loading" :error="error" :empty="!experiments.length" empty-title="尚未创建实验" empty-text="先准备数据集和 Agent 配置，再创建实验。" @retry="load"><template #empty-action><ElButton @click="edit()">创建实验</ElButton></template><div class="table-scroll"><table><thead><tr><th>实验与目的</th><th>冻结输入来源</th><th>候选标签</th><th>操作</th></tr></thead><tbody><tr v-for="item in experiments" :key="item.id" :class="{ selected: item.id === selected?.id }"><td><button class="text-link record-title" @click="select(item)">{{ item.name }}</button><p class="table-subtext">{{ item.purpose || '未填写目的' }}</p></td><td>数据集 #{{ item.dataset_id }} · Agent #{{ item.agent_config_id }}<p class="table-subtext">{{ date(item.created_at) }}</p></td><td>{{ item.version_label || '未填写' }}</td><td><div class="row-actions"><ElButton size="small" @click="select(item)">查看运行</ElButton><ElButton size="small" @click="edit(item)">编辑</ElButton><ElButton size="small" @click="remove(item)">删除</ElButton></div></td></tr></tbody></table></div><div v-if="total > 20" class="pagination"><ElPagination v-model:current-page="page" :total="total" :page-size="20" layout="prev, pager, next" @current-change="load" /></div></AsyncState></section>
  <section v-if="selected" class="panel section-gap"><div class="panel-heading"><div><div class="eyebrow">RUN HISTORY</div><h2>{{ selected.name }}</h2></div><ElButton type="primary" @click="prepareStart">启动新运行</ElButton></div><AsyncState :loading="historyLoading" :error="historyError" :empty="!runs.length" empty-title="这个实验尚无运行" empty-text="启动后会先冻结当前启用用例及执行条件。" @retry="loadHistory"><div class="table-scroll"><table><thead><tr><th>运行身份</th><th>来源 / 状态</th><th>持久进度</th><th>质量计数</th><th>操作</th></tr></thead><tbody><tr v-for="run in runs" :key="run.id"><td class="small"><span class="mono">{{ run.id.slice(0, 8) }}</span><p class="table-subtext">{{ date(run.created_at) }}</p></td><td><ElTag size="small" type="info">{{ sourceNames[run.source_type] || run.source_type }}</ElTag><p class="table-subtext">{{ stateNames[run.status] || run.status }}</p></td><td>已执行 {{ run.progress?.executed ?? '未知' }}/{{ run.total_cases }}<p class="table-subtext">已评分 {{ run.progress?.evaluated ?? '未知' }}/{{ run.total_cases }}</p></td><td v-if="run.summary">P {{ run.summary.P }} · F {{ run.summary.F }} · U {{ run.summary.U }}</td><td v-else>尚无评分</td><td><div class="row-actions"><ElButton size="small" @click="remember({ run: run.id, score_set: undefined }); track(run.id)">追踪进度</ElButton><RouterLink class="text-link" :to="{ path: '/reports', query: { run: run.id } }">报告</RouterLink><ElButton size="small" @click="prepareRescore(run)">重新评分</ElButton></div></td></tr></tbody></table></div><div v-if="runTotal > 20" class="pagination"><ElPagination v-model:current-page="runPage" :total="runTotal" :page-size="20" layout="prev, pager, next" @current-change="loadHistory" /></div></AsyncState></section>
  <section v-if="currentRun || progressError || progressLoading" class="panel section-gap"><div class="panel-heading"><h2>持久任务进度</h2><ElButton size="small" :loading="progressLoading" @click="retryProgress">重新查询</ElButton></div><div class="panel-body"><ProblemBox :error="progressError" /><p v-if="progressError" class="warning-line">查询失败，以下为上次成功读取的状态；请重新查询恢复。</p><template v-if="currentRun"><p class="mono small">{{ currentRun.id }}</p><p>{{ stateNames[currentScoreSet?.status || currentRun.status] || currentScoreSet?.status || currentRun.status }} · 已评分 {{ (currentScoreSet?.progress || currentRun.progress)?.evaluated ?? '未知' }}/{{ currentRun.total_cases }} <span v-if="progressLoading" class="muted small">正在读取…</span></p><progress class="run-progress" :value="(currentScoreSet?.progress || currentRun.progress)?.evaluated || 0" :max="currentRun.total_cases" /><p v-if="currentScoreSet" class="small muted">重评分集 {{ currentScoreSet.id }}。不会调用 Agent，原用量只作为执行事实展示。</p><SummaryPanel v-if="currentRun.summary && !currentScoreSet" :summary="currentRun.summary" /><details class="raw-detail"><summary>冻结快照与错误诊断</summary><pre>{{ pretty({ snapshot: currentRun.snapshot, sha256: currentRun.snapshot_sha256, error: currentRun.error }) }}</pre></details></template></div></section>
  <section class="panel section-gap"><div class="panel-heading"><h2>比较两次运行与评分集</h2><ElButton :loading="comparing" @click="compare">比较所选结果</ElButton></div><div class="panel-body"><div class="compare-pickers"><RunPicker :run-id="left" :score-set-id="leftScore" label="左侧运行" @change="pickLeft" /><RunPicker :run-id="right" :score-set-id="rightScore" label="右侧运行" @change="pickRight" /></div><ProblemBox :error="compareError" /><div v-if="comparing" class="small muted" role="status">正在核对冻结条件与有效配对…</div><template v-if="comparison"><p :class="comparison.comparable ? 'notice' : 'warning-line'">{{ comparison.comparable ? '数据、Judge 与规则口径一致；差值使用逐指标共同有效样本。' : '条件存在差异，仅并排展示，不能直接归因于 Agent 改进。' }}</p><ul class="limitation-list"><li v-for="reason in comparison.limitations" :key="reason">{{ reason }}</li></ul><p class="small">实际版本：{{ comparison.version_comparison.status }} · {{ comparison.version_comparison.verified_change ? '观测支持实际变化' : '尚未证明实际配置发生变化' }}</p><ul class="limitation-list"><li v-for="reason in comparison.version_comparison.limitations" :key="reason">{{ reason }}</li></ul><details class="raw-detail"><summary>查看两侧实际版本条件</summary><pre>{{ pretty(comparison.version_comparison.dimensions) }}</pre></details><div class="comparison-summary"><div><h3>左侧结果</h3><SummaryPanel :summary="comparison.left.summary" /></div><div><h3>右侧结果</h3><SummaryPanel :summary="comparison.right.summary" /></div></div><div class="table-scroll"><table><thead><tr><th>指标</th><th>共同有效数</th><th>左均值</th><th>右均值</th><th>差值 · 右−左</th><th>未配对原因</th></tr></thead><tbody><tr v-for="item in comparison.metrics" :key="item.metric"><td>{{ metricNames[item.metric] || item.metric }}<details v-if="item.pairs.length" class="inline-detail"><summary>共同样本</summary><p v-for="pair in item.pairs" :key="pair.case_key"><RouterLink class="text-link" :to="{ path: '/evaluations', query: { case: pair.left_case_run_id, score_set: comparison.left.score_set.id } }">{{ pair.case_key }} 左</RouterLink> / <RouterLink class="text-link" :to="{ path: '/evaluations', query: { case: pair.right_case_run_id, score_set: comparison.right.score_set.id } }">右</RouterLink> · {{ number(pair.left_value) }} → {{ number(pair.right_value) }}</p></details></td><td>{{ item.paired_count }}</td><td>{{ number(item.left_mean) }}<p class="table-subtext">左侧有效 {{ item.left_valid_count }} · {{ item.mean_scope === 'COMMON_VALID_PAIRS' ? '均值取共同集合' : '均值取左侧独立集合' }}</p></td><td>{{ number(item.right_mean) }}<p class="table-subtext">右侧有效 {{ item.right_valid_count }} · {{ item.mean_scope === 'COMMON_VALID_PAIRS' ? '均值取共同集合' : '均值取右侧独立集合' }}</p></td><td>{{ number(item.delta) }}</td><td class="small">{{ pretty(item.unpaired_reasons) }}</td></tr></tbody></table></div><h3 class="section-gap">逐题差异</h3><div class="table-scroll"><table><thead><tr><th>用例</th><th>左侧结论</th><th>右侧结论</th><th>配对条件</th></tr></thead><tbody><tr v-for="item in comparison.cases" :key="item.case_key"><td class="mono">{{ item.case_key }}</td><td><RouterLink v-if="item.left_case_run_id" class="text-link" :to="{ path: '/evaluations', query: { case: item.left_case_run_id, score_set: comparison.left.score_set.id } }">{{ stateNames[item.left_conclusion || 'UNDETERMINED'] || item.left_conclusion }}</RouterLink></td><td><RouterLink v-if="item.right_case_run_id" class="text-link" :to="{ path: '/evaluations', query: { case: item.right_case_run_id, score_set: comparison.right.score_set.id } }">{{ stateNames[item.right_conclusion || 'UNDETERMINED'] || item.right_conclusion }}</RouterLink></td><td>{{ item.content_match ? '内容一致' : item.reason || '内容不一致或缺失' }}</td></tr></tbody></table></div></template><p v-else-if="!comparing && !compareError" class="muted small">选择左右运行及评分集后查看条件限制、指标和逐题记录。</p></div></section>
  <FormModal v-if="modal" :title="editId ? '编辑实验' : '创建实验'" :saving="saving" @close="!saving && (modal = false)"><form class="editor-form" @submit.prevent="save"><ProblemBox :error="formError" /><label>实验名称 <span class="required">*</span><input v-model="form.name" maxlength="200" /></label><div class="form-grid"><label>数据集 <span class="required">*</span><select v-model="form.dataset_id" :disabled="choicesLoading"><option :value="0">选择数据集</option><option v-for="item in datasets" :key="item.id" :value="item.id">{{ item.name }} · 启用 {{ item.enabled_cases }} 条</option></select></label><label>Agent 配置 <span class="required">*</span><select v-model="form.agent_config_id" :disabled="choicesLoading"><option :value="0">选择连接</option><option v-for="item in agents" :key="item.id" :value="item.id" :disabled="!item.enabled">{{ item.name }} · {{ sourceNames[item.source_type] }}{{ !item.enabled ? '（已停用）' : '' }}</option></select></label></div><label>候选版本标签<input v-model="form.version_label" maxlength="200" placeholder="例如 Prompt B，实际版本由运行观测核验" /></label><label>实验目的<textarea v-model="form.purpose" rows="3" maxlength="10000" /></label><div class="form-actions"><ElButton @click="modal = false" :disabled="saving">取消</ElButton><ElButton type="primary" native-type="submit" :loading="saving" :disabled="choicesLoading">保存实验</ElButton></div></form></FormModal>
  <FormModal v-if="startModal || rescoreModal" :title="rescoreModal ? '使用已有回答重新评分' : '启动新运行'" :saving="saving" wide @close="!saving && (startModal = false, rescoreModal = false)"><form class="editor-form" @submit.prevent="rescoreModal ? rescore() : start()"><ProblemBox :error="formError" /><p class="field-help">{{ rescoreModal ? '创建独立 RESCORE 评分集，旧评分、回答与工具事实保留。' : '启动将冻结当前启用用例并调用所选连接；真实连接可能产生模型费用。' }} 配置只接受凭证环境引用名。</p><label>Judge 配置 JSON<textarea v-model="judgeJson" rows="5" class="mono" spellcheck="false" /><small>字段：base_url、model、credential_ref、source_type；空对象采用后端默认配置，缺少有效 Judge 时保留评分故障。</small></label><label>规则配置 JSON<textarea v-model="ruleJson" rows="4" class="mono" spellcheck="false" /><small>可配置 quality_thresholds 与 response_time_ms；具体类型由后端校验。</small></label><label v-if="!rescoreModal">执行预算 JSON<textarea v-model="budgetJson" rows="4" class="mono" spellcheck="false" /><small>真实运行必须显式配置总时长与调用上限，预算不会自动扩大。</small></label><p v-if="!rescoreModal" class="small mono muted">幂等请求号：{{ requestId }}；保存超时后保持本号，先查询运行历史核对。</p><div class="form-actions"><ElButton :disabled="saving" @click="startModal = false; rescoreModal = false">取消</ElButton><ElButton type="primary" native-type="submit" :loading="saving">{{ rescoreModal ? '创建重评分集' : '冻结并启动运行' }}</ElButton></div></form></FormModal>
</template>
